<?php
require_once __DIR__ . '/includes/auth.php';requireLogin();$pdo=db();$uid=userId();$pageTitle='Target';$activePage='target.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare('DELETE FROM financial_goals WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Target berhasil dihapus.');redirect('target.php');}if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$target=parseAmount($_POST['target_amount']??0);$current=parseAmount($_POST['current_amount']??0);$deadline=(string)($_POST['deadline']??'');$category=trim((string)$_POST['category']);$status=(string)$_POST['status'];$desc=trim((string)$_POST['description']);if($name===''||$target<=0||$current<0||!validDate($deadline)||$category===''||!in_array($status,['Aktif','Selesai','Ditunda'],true)){flash('error','Lengkapi target, nominal, deadline, kategori, dan status.');redirect('target.php?action='.($id?'edit&id='.$id:'add'));}if($current>$target)$current=$target;if($id){$st=$pdo->prepare('UPDATE financial_goals SET name=?,target_amount=?,current_amount=?,deadline=?,category=?,status=?,description=? WHERE id=? AND user_id=?');$st->execute([$name,$target,$current,$deadline,$category,$status,$desc,$id,$uid]);}else{$st=$pdo->prepare('INSERT INTO financial_goals(user_id,name,target_amount,current_amount,deadline,category,status,description) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$uid,$name,$target,$current,$deadline,$category,$status,$desc]);}flash('success','Target berhasil disimpan.');redirect('target.php');}}
$st=$pdo->prepare('SELECT * FROM financial_goals WHERE user_id=? ORDER BY status="Selesai",deadline IS NULL,deadline');$st->execute([$uid]);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare('SELECT * FROM financial_goals WHERE id=? AND user_id=?');$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'name'=>'','target_amount'=>'','current_amount'=>'','deadline'=>date('Y-m-d',strtotime('+6 months')),'category'=>'Barang','status'=>'Aktif','description'=>''];$user=currentUser($pdo);require __DIR__.'/includes/header.php';$cats=['Barang','Kendaraan','Rumah','Liburan','Pendidikan','Dana Darurat','Bisnis','Lainnya'];
?>
<div class="page-heading"><div><p class="eyebrow">Rencana masa depan</p><h1>Target Keuangan</h1><p>Ubah keinginan menjadi target yang bisa dipantau.</p></div><a class="btn btn-primary" href="?action=add"><i data-lucide="plus"></i> Tambah Target</a></div>
<section class="grid-two"><?php if(!$rows): ?><div class="card empty-state" style="grid-column:1/-1"><div class="empty-icon"><i data-lucide="goal"></i></div><strong>Belum ada target keuangan.</strong><p>Tentukan satu target kecil hari ini dan mulai isi progresnya.</p><a class="btn btn-primary btn-sm" href="?action=add">Tambah Target</a></div><?php else: ?><?php foreach($rows as $row):$pct=percentage((float)$row['current_amount'],(float)$row['target_amount']);$remaining=max(0,(float)$row['target_amount']-(float)$row['current_amount']);$months=max(1,(int)ceil((strtotime($row['deadline'])-time())/(30*86400)));$perMonth=$remaining/$months;?><article class="card"><div class="card-header"><div><span class="badge <?= $row['status']==='Selesai'?'success':($row['status']==='Ditunda'?'warning':'neutral') ?>"><?=e($row['status'])?></span><h2 class="card-title" style="margin-top:10px"><?=e($row['name'])?></h2><p class="card-subtitle"><?=e($row['category'])?> · Deadline <?=e(date('d/m/Y',strtotime($row['deadline'])))?></p></div><div class="actions"><a class="btn btn-ghost btn-sm icon-btn" href="?action=edit&id=<?=(int)$row['id']?>"><i data-lucide="pencil"></i></a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-ghost btn-sm icon-btn" data-confirm="Hapus target ini?" type="submit"><i data-lucide="trash-2"></i></button></form></div></div><div class="stat-value"><?=formatRupiah($row['current_amount'])?> <small class="form-hint">/ <?=formatRupiah($row['target_amount'])?></small></div><div class="progress-meta"><span>Progress</span><strong><?=number_format($pct,1,',','.')?>%</strong></div><div class="progress-line"><div class="progress-fill success" style="width:<?=$pct?>%"></div></div><div class="progress-meta"><span>Tersisa <?=formatRupiah($remaining)?></span><span>Per bulan ± <?=formatRupiah($perMonth)?></span></div></article><?php endforeach;?><?php endif;?></section>
<div class="modal <?=$edit?'is-open':''?>" id="target-modal"><div class="modal-head"><div><h3><?=$edit&&$edit['id']?'Edit':'Tambah'?> Target</h3><p>Progress target dihitung otomatis dari nominal saat ini.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="form-field"><label>Nama target</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" placeholder="Contoh: Laptop kerja" required></div><div class="form-field"><label>Kategori</label><select class="select" name="category"><?php foreach($cats as $cat):?><option <?=$cat===($edit['category']??'')?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select></div><div class="form-field"><label>Target nominal</label><input class="input" data-amount name="target_amount" value="<?=e($edit['target_amount']??'')?>" required></div><div class="form-field"><label>Nominal saat ini</label><input class="input" data-amount name="current_amount" value="<?=e($edit['current_amount']??'')?>" required></div><div class="form-field"><label>Deadline</label><input class="input" type="date" name="deadline" value="<?=e($edit['deadline']??'')?>" required></div><div class="form-field"><label>Status</label><select class="select" name="status"><?php foreach(['Aktif','Selesai','Ditunda'] as $status):?><option <?=$status===($edit['status']??'Aktif')?'selected':''?>><?=$status?></option><?php endforeach;?></select></div><div class="form-field full"><label>Deskripsi</label><textarea class="textarea" name="description" placeholder="Kenapa target ini penting?"><?=e($edit['description']??'')?></textarea></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan Target</button></div></form></div>
<?php require __DIR__.'/includes/footer.php'; ?>